type HostOverview={name:string,docker_version:string,operating_system:string,os_type:string,architecture:string,kernel_version:string,storage_driver:string,docker_root_dir:string,cpus:number,memory_total_bytes:number,memory_source?:string,memory_diagnostic?:string,containers_total:number,containers_running:number,containers_stopped:number,images_total:number,images_in_use:number,images_unused:number,images_dangling:number,image_disk_bytes:number,image_reclaimable_bytes:number,image_disk_exact:boolean,images_rollback_protected:number,images_cleanup_eligible:number,build_cache_bytes:number,build_cache_reclaimable_bytes:number,container_cpu_percent:number,container_memory_bytes:number,container_memory_percent:number,container_stats_available:boolean,container_stats_error?:string,images?:ImageSummary[],collected_at:string,error?:string}
