type Container={id:string,name:string,image:string,image_id?:string,state:string,status:string,ports:string,networks:string,created_at:string,stack_name:string,stack_service:string,stack_type:string,system_managed?:boolean,system_role?:string,policy:Policy,update:Cache,version:VersionInfo,config_drift?:ConfigDrift}
