const api=async<T=any>(path:string,opts?:RequestInit):Promise<T>=>{const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(opts?.headers||{})}});const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||`HTTP ${r.status}`);return body}
const fmt=(v?:string)=>v?new Date(v).toLocaleString('de-DE'):'—'
const fmtBytes=(v?:number)=>{const n=Number(v||0);if(!Number.isFinite(n)||n<=0)return '0 B';const u=['B','KiB','MiB','GiB','TiB','PiB'];let x=n,i=0;while(x>=1024&&i<u.length-1){x/=1024;i++}return `${x>=100||i===0?x.toFixed(0):x>=10?x.toFixed(1):x.toFixed(2)} ${u[i]}`}
const fmtPct=(v?:number)=>Number.isFinite(Number(v))?`${Number(v||0).toFixed(1)}%`:'—'
const memorySourceLabel=(v?:string)=>v==='docker-info'?'Docker info':v==='docker-stats-limit'?'Docker stats':v==='unavailable'?'Unavailable':v||''
const hostAddress=(endpoint?:string)=>{const v=String(endpoint||'');if(v.startsWith('unix://'))return 'Local socket';const m=v.match(/^tcp:\/\/([^:/]+|\[[^\]]+\]):\d+$/);return m?m[1].replace(/^\[|\]$/g,''):v||'—'}
const shortDigest=(v?:string)=>{const raw=String(v||'').trim();if(!raw)return '';const body=raw.startsWith('sha256:')?raw.slice(7):raw;return `${raw.startsWith('sha256:')?'sha256:':''}${body.slice(0,12)}${body.length>12?'…':''}`}
const sameDigest=(a?:string,b?:string)=>!!String(a||'').trim()&&String(a||'').trim().toLowerCase()===String(b||'').trim().toLowerCase()
const isSnoozedUpdate=(c:Container)=>!!c.update?.snoozed_digest&&sameDigest(c.update.snoozed_digest,c.update.latest_digest)&&!sameDigest(c.update.current_digest,c.update.latest_digest)
const imageStatus=(c:Container)=>{if(c.system_managed)return{key:'system',label:'Managed in Settings',tone:'gray',detail:'Owner maintenance'};if(c.update?.last_error)return{key:'unavailable',label:'Check unavailable',tone:'red',detail:c.update.last_error};if(isSnoozedUpdate(c))return{key:'snoozed',label:'Update snoozed',tone:'yellow',detail:'This digest is skipped until a newer image appears'};if(c.update?.update_available){const installed=String(c.version?.installed_version||'').trim(),latest=String(c.version?.latest_version||'').trim();if(installed&&latest)return{key:'update',label:'Update available',tone:'blue',detail:installed===latest?'Same version label · image digest changed':'Image digest changed'};return{key:'update',label:'New image available',tone:'blue',detail:'Digest changed · version metadata incomplete'}}if(c.update?.last_checked_at)return{key:'current',label:'Up to date',tone:'green',detail:'Image digest matches'};return{key:'unchecked',label:'Not checked',tone:'gray',detail:'No digest comparison yet'}}
const humanCron=(cron:string)=>{const p=String(cron||'').trim().split(/\s+/);if(p.length!==5)return cron||'Invalid schedule';const[min,hour,dom,mon,dow]=p;const hh=String(Number(hour)).padStart(2,'0');const mm=String(Number(min)).padStart(2,'0');if(/^\d+$/.test(min)&&/^\d+$/.test(hour)&&dom==='*'&&mon==='*'&&dow==='*')return `Daily at ${hh}:${mm}`;if(/^\d+$/.test(min)&&/^\d+$/.test(hour)&&dom==='*'&&mon==='*'&&/^[0-6]$/.test(dow)){const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];return `${days[Number(dow)]} at ${hh}:${mm}`}return cron}
const safeIds=(v?:number[]|null):number[]=>Array.isArray(v)?v:[]
const reportClientError=(error:any,stack='')=>{const message=error instanceof Error?error.message:String(error||'Unknown browser error');const trace=error instanceof Error?error.stack||stack:stack;fetch('/api/client-errors',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,stack:trace,url:window.location.href})}).catch(()=>{})}
class PageErrorBoundary extends React.Component<{children:React.ReactNode,page:string},{error:Error|null}>{state:{error:Error|null}={error:null};static getDerivedStateFromError(error:Error){return{error}}componentDidCatch(error:Error,info:React.ErrorInfo){reportClientError(error,info.componentStack||'')}render(){if(this.state.error)return <Card><div className="space-y-3"><Badge tone="red">Page error</Badge><h2 className="text-lg font-semibold">This page could not be rendered.</h2><p className="text-sm text-zinc-500">The browser error was written to the controller log for the next support bundle.</p><pre className="overflow-auto rounded-lg border border-zinc-800 bg-zinc-950/50 p-3 text-xs text-red-300">{this.state.error.message}</pre><Button kind="primary" onClick={()=>window.location.reload()}>Reload interface</Button></div></Card>;return this.props.children}}

