 const openNetworks=async(h:Host)=>{setNetworkBusy(true);try{const x:any=await api(`/api/hosts/${h.id}/networks`),data:NetworkSummary[]=Array.isArray(x)?x:[];setHostNetworks(v=>({...v,[h.id]:data}));setHostInventoryErrors(v=>({...v,[h.id]:{...(v[h.id]||{}),networks:undefined}}));setNetworkDetails({host:h,data})}catch(e:any){setHostInventoryErrors(v=>({...v,[h.id]:{...(v[h.id]||{}),networks:e.message||'Network inventory unavailable'}}));notify(e.message)}finally{setNetworkBusy(false)}}
 const pruneNetworks=async(h:Host)=>{const data=networkDetails?.host.id===h.id?networkDetails.data:await api<NetworkSummary[]>(`/api/hosts/${h.id}/networks`);const eligible=data.filter(n=>n.unused&&!n.system&&!n.rollback_protected).length,protectedCount=data.filter(n=>n.rollback_protected&&!n.in_use).length;if(!eligible)return;if(!confirm(`Delete ${eligible} unused custom Docker network${eligible===1?'':'s'} on ${h.name}?\n\nDocker default networks, networks in use${protectedCount?' and rollback-protected networks':''} are kept.`))return;setNetworkAction(h.id);try{const x:any=await api(`/api/hosts/${h.id}/networks/prune`,{method:'POST'});notify(`Network cleanup complete · ${x.result.removed_networks.length} removed · ${x.result.protected_networks||0} rollback-protected`);await openNetworks(h)}catch(e:any){notify(e.message)}finally{setNetworkAction(0)}}
